<template>
  <div class="settings-card">
    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('pages_to_process') }}</span>
      </div>
      <div class="settings-toggle-selects">
        <q-input
          dense
          outlined
          tabindex="0"
          type="number"
          min="0"
          debounce="500"
          class="back-white"
          data-cy="restrict_to_pages"
          data-test="sa-restrict-to-pages"
          :label="$t('pages_to_process_field_label')"
          v-model="user_settings[restrict_to_pages]"
          @update:model-value="(val: any) => saveSettings(restrict_to_pages, val)"
        />
        <div class="pages-to-process-summary" data-test="pages-to-process-summary">
          {{ pagesSummary }}
        </div>
        <div class="pages-to-process-description">
          {{ $t('pages_to_process_description') }}
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  data() {
    return {
      restrict_to_pages: 'RESTRICT_TO_PAGES',
    };
  },
  computed: {
    // Empty or 0 means no limit, so every page is processed.
    pagesSummary(): string {
      const pages = parseInt(this.user_settings[this.restrict_to_pages], 10);
      if (!pages || pages < 1) {
        return this.$t('pages_to_process_summary_all');
      }
      if (pages === 1) {
        return this.$t('pages_to_process_summary_one');
      }
      return this.$t('pages_to_process_summary', { count: pages });
    },
  },
  methods: {
    async saveSettings(key: string, value: any) {
      this.showLoading();
      try {
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      updateSetting,
      user_settings,
    };
  },
});
</script>

