<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{
          $t('table_extraction_setting_label')
        }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle
          size="xs"
          data-test="sa-table-extraction-setting"
          v-model="user_settings[table_extraction_setting]"
          @update:model-value="
            saveSettings(
              table_extraction_setting,
              user_settings[table_extraction_setting],
            )
          "
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{
          $t('ai_table_extraction')
        }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle
          size="xs"
          data-test="sa-use-ai-table-extraction"
          v-model="user_settings[AI_table_extraction_setting]"
          @update:model-value="
            saveSettings(
              AI_table_extraction_setting,
              user_settings[AI_table_extraction_setting],
            )
          "
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">
          {{ $t('use_table_extraction_vision') }}
          <q-icon
            name="info"
            size="20px"
            class="text-primary cursor-pointer q-ml-sm"
          >
            <q-tooltip anchor="top middle" self="bottom middle">
              {{ $t('vision_mode_hint') }}
            </q-tooltip>
          </q-icon>
        </span>
      </div>
      <div class="settings-toggle-selects">
        <q-select
          outlined
          dense
          class="s-field back-white"
          data-testid="vision-mode-select"
          data-test="sa-table-extraction-vision-mode"
          :model-value="visionMode"
          :options="visionModeOptions"
          emit-value
          map-options
          :label="$t('use_table_extraction_vision')"
          @update:model-value="saveVisionMode"
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{
          $t('use_structured_extraction')
        }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle
          size="xs"
          data-test="sa-use-structured-extraction"
          v-model="user_settings[table_extraction_use_structured_extraction]"
          @update:model-value="
            saveSettings(
              table_extraction_use_structured_extraction,
              user_settings[table_extraction_use_structured_extraction],
            )
          "
        />
      </div>
    </div>
    <AiSchemaPreview
      v-if="user_settings[table_extraction_use_structured_extraction]"
    />

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{
          $t('costing_table_extraction')
        }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle
          size="xs"
          data-test="sa-charges-table-extraction"
          v-model="user_settings[charges_table_extraction]"
          @update:model-value="
            saveSettings(
              charges_table_extraction,
              user_settings[charges_table_extraction],
            )
          "
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{
          $t('auto_extract_tax_code')
        }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle
          size="xs"
          data-test="sa-auto-extract-tax-code"
          v-model="user_settings[auto_extract_tax_code_setting]"
          @update:model-value="
            saveSettings(
              auto_extract_tax_code_setting,
              user_settings[auto_extract_tax_code_setting],
            )
          "
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{
          $t('save_extraction_rules_admin_only')
        }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle
          size="xs"
          data-test="sa-only-admin-can-save-rules"
          v-model="user_settings[only_admin_can_save_rules]"
          @update:model-value="
            saveSettings(
              only_admin_can_save_rules,
              user_settings[only_admin_can_save_rules],
            )
          "
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">
          {{ $t('extract_hidden_fields') }}
          <q-icon
            name="info"
            size="20px"
            class="text-primary cursor-pointer q-ml-sm"
          >
            <q-tooltip anchor="top middle" self="bottom middle">
              <div style="max-width: 400px">
                {{ $t('extract_hidden_fields_info') }}
              </div>
            </q-tooltip>
          </q-icon>
        </span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle
          size="xs"
          data-test="sa-extract-hidden-fields"
          v-model="user_settings[extract_hidden_fields]"
          @update:model-value="
            saveSettings(
              extract_hidden_fields,
              user_settings[extract_hidden_fields],
            )
          "
        />
      </div>
    </div>

    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">
          {{ $t('ai_model') }}
          <q-icon
            name="info"
            size="20px"
            class="text-primary cursor-pointer q-ml-sm"
          >
            <q-tooltip anchor="top middle" self="bottom middle">
              {{ getTooltipLabel(user_settings[ai_model]) }}
            </q-tooltip>
          </q-icon>
        </span>
      </div>
      <div class="settings-toggle-selects">
        <q-select
          outlined
          dense
          class="s-field back-white"
          data-test="sa-ai-model"
          v-model="user_settings[ai_model]"
          :options="aiModelList"
          :display-value="tierLabelFor(user_settings[ai_model])"
          @update:model-value="
            (val: string) => {
              saveSettings(ai_model, val);
            }
          "
          emit-value
          map-options
          :label="$t('ai_model')"
        />
      </div>
    </div>
  </div>

  <Loader />

  <q-dialog v-model="confirm_version_update" persistent>
    <q-card>
      <q-card-section class="row items-center">
        <q-avatar icon="block" color="primary" text-color="white" />
        <span class="q-ml-sm">{{ $t('this_confirm_version_update') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn
          class="bg-grey-3"
          :label="$t('cancel')"
          @click="closeVersionUpdateWarningDialog"
        />

        <q-btn
          color="primary"
          class="q-mr-sm"
          data-cy="setvatfield"
          :label="$t('confirm')"
          @click="updateTEVersion"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import Loader from 'src/components/Loader.vue';
import AiSchemaPreview from './AiSchemaPreview.vue';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import {
  CONSTANTS,
  aiModelList,
  getAiTierLabel,
  table_extraction_setting,
  charges_table_extraction,
  AI_table_extraction_setting,
  table_extraction_use_vision_setting,
  table_extraction_vision_mode_setting,
  visionModeList,
  resolveVisionMode,
  legacyVisionFor,
  auto_extract_tax_code_setting,
  table_extraction_use_structured_extraction,
} from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: ['showSpinner'],
  components: {
    AiSchemaPreview,
    Loader,
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == false && oldVal == true) {
          this.hideLoading();
          this.setDefaultSettings();
        } else {
          this.showLoading();
        }
      },
    },
  },
  data() {
    return {
      tbx_ext_version: 'TBL_EXT_VERSION',
      tbx_ext_version_prev: '',
      table_extraction_setting,
      charges_table_extraction,
      AI_table_extraction_setting,
      table_extraction_use_vision_setting,
      table_extraction_vision_mode_setting,
      table_extraction_use_structured_extraction,
      auto_extract_tax_code_setting,
      ai_model: CONSTANTS.ai_model,
      aiModelList: aiModelList,
      only_admin_can_save_rules: CONSTANTS.only_admin_can_save_rules,
      extract_hidden_fields: CONSTANTS.extract_hidden_fields,
    };
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    const confirm_version_update = ref(false);

    return {
      updateSetting,
      closeVersionUpdateWarningDialog: () => {
        confirm_version_update.value = false;
      },
      user_settings,
      loading_settings,
      confirm_version_update,
    };
  },
  mounted: function () {
    this.setDefaultSettings();
  },
  computed: {
    visionMode(): string {
      return resolveVisionMode(
        this.user_settings[table_extraction_vision_mode_setting],
        this.user_settings[table_extraction_use_vision_setting],
      );
    },
    visionModeOptions(): { label: string; value: string }[] {
      return visionModeList.map((m) => ({
        label: this.$t(m.label),
        value: m.value,
      }));
    },
  },
  methods: {
    async saveVisionMode(mode: 'off' | 'vision' | 'hybrid' | 'auto') {
      // CORE-6092: the new mode, and the legacy switch kept in step for
      // services that read only TABLE_EXTRACTION_USE_VISION.
      this.user_settings[table_extraction_vision_mode_setting] = mode;
      this.user_settings[table_extraction_use_vision_setting] =
        legacyVisionFor(mode);
      await this.saveSettings(table_extraction_vision_mode_setting, mode);
      await this.saveSettings(
        table_extraction_use_vision_setting,
        legacyVisionFor(mode),
      );
    },
    updateTEVersion() {
      this.this.confirm_version_update = false;
      this.saveSettings(this.tbx_ext_version, this.tbx_ext_version_val);
    },

    setDefaultSettings() {
      // if (this.user_settings[this.tbx_ext_version]) {
      //   const value = this.user_settings[this.tbx_ext_version];
      // }
      if (!this.user_settings[this.charges_table_extraction]) {
        this.user_settings[this.charges_table_extraction] = false;
      }
      if (!this.user_settings[this.AI_table_extraction_setting]) {
        this.user_settings[this.AI_table_extraction_setting] = false;
      }
      if (!this.user_settings[this.table_extraction_setting]) {
        this.user_settings[this.table_extraction_setting] = false;
      }

      if (!this.user_settings[this.table_extraction_use_vision_setting]) {
        this.user_settings[this.table_extraction_use_vision_setting] = false;
      }
      if (!this.user_settings[this.auto_extract_tax_code_setting]) {
        this.user_settings[this.auto_extract_tax_code_setting] = false;
      }
      // DRFS-835: extraction treats an unset EXTRACT_HIDDEN_FIELDS as on, so
      // show it on until the org turns it off.
      if (
        this.user_settings[this.extract_hidden_fields] === undefined ||
        this.user_settings[this.extract_hidden_fields] === null
      ) {
        this.user_settings[this.extract_hidden_fields] = true;
      }
      if (!this.user_settings[this.ai_model]) {
        this.user_settings[this.ai_model] = CONSTANTS.DEFAULT_AI_MODEL;
      }
      if (
        !this.user_settings[this.table_extraction_use_structured_extraction]
      ) {
        this.user_settings[this.table_extraction_use_structured_extraction] =
          false;
      }
    },

    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }

      this.showLoading();
      await this.updateSetting(key, value);
      this.hideLoading();
      notify.success(this.$t('MSG_SAVE'));
    },

    getTooltipLabel(ai_model: string) {
      // DOCB-13483: resolve through the shared tier helper so a stored value
      // that is no longer in aiModelList (retired gpt-5.4-nano, legacy ids
      // like gpt-4o, fine-tunes) still shows its correct tier cost instead
      // of the raw key "undefined_ai_token_cost".
      return this.$t(
        getAiTierLabel(ai_model).toLowerCase().replace(/\s+/g, '_') +
          '_ai_token_cost',
      );
    },

    tierLabelFor(ai_model: string) {
      return getAiTierLabel(ai_model);
    },
  },
});
</script>

<style lang="scss" scoped></style>
