<template>
  <!-- CORE-6102: what structured extraction requests for a doc type. -->
  <div class="ai-schema-preview q-pa-md" data-testid="ai-schema-preview">
    <div class="row items-start justify-between q-col-gutter-md">
      <div class="col">
        <div class="text-subtitle1 text-weight-medium">{{ $t('ai_schema_preview_title') }}</div>
        <div class="text-caption text-grey-8">{{ $t('ai_schema_preview_hint') }}</div>
      </div>
      <div class="col-auto row q-gutter-sm items-center">
        <q-select
          dense
          outlined
          emit-value
          map-options
          style="min-width: 220px"
          data-testid="ai-schema-preview-doc-type"
          :label="$t('document_type')"
          :options="docTypeOptions"
          v-model="docType"
          @update:model-value="load"
        />
        <q-btn flat no-caps color="primary" :label="$t('ai_schema_preview_edit_fields')" :to="`/settings/fields/${docType}`" />
        <q-btn flat no-caps color="primary" :label="$t('ai_schema_preview_edit_columns')" :to="`/settings/custom-columns/${docType}`" />
      </div>
    </div>

    <div v-if="loading" class="q-mt-md"><q-spinner size="24px" color="primary" /></div>
    <div v-else-if="error" class="q-mt-md text-negative">{{ error }}</div>
    <template v-else-if="preview">
      <div class="row q-col-gutter-lg q-mt-sm">
        <div class="col-12 col-md-6">
          <div class="text-overline text-grey-8">
            {{ $t('ai_schema_preview_fields') }} · {{ preview.fields.requested.length }}
          </div>
          <div class="row q-gutter-xs">
            <q-chip
              v-for="f in preview.fields.requested"
              :key="f.name"
              dense
              square
              :outline="f.source !== 'explicit_on'"
              color="primary"
              text-color="primary"
              class="ai-chip"
            >{{ f.name }}<span v-if="f.source === 'default_on'" class="q-ml-xs text-caption">· {{ $t('use_ai_standard') }}</span></q-chip>
          </div>
          <q-banner
            v-for="f in preview.fields.default_switched_off"
            :key="'off-' + f.name"
            dense
            rounded
            class="q-mt-sm bg-orange-1 text-orange-10"
            data-testid="ai-schema-preview-default-off"
          >{{ $t('ai_schema_preview_default_off', { name: f.name }) }}</q-banner>
        </div>
        <div class="col-12 col-md-6">
          <div v-for="(t, tableName) in preview.tables" :key="tableName" class="q-mb-sm">
            <div class="text-overline text-grey-8">
              {{ tableName }} · {{ $t('ai_schema_preview_columns') }} · {{ t.requested.length }}
            </div>
            <div class="row q-gutter-xs">
              <q-chip
                v-for="c in t.requested"
                :key="c.name"
                dense
                square
                :outline="c.source !== 'explicit_on'"
                color="primary"
                text-color="primary"
                class="ai-chip"
              >{{ c.name }}<span v-if="c.source === 'default_on'" class="q-ml-xs text-caption">· {{ $t('use_ai_standard') }}</span></q-chip>
            </div>
            <template v-if="t.not_requested.length">
              <div class="text-overline text-grey-8 q-mt-xs">{{ $t('ai_schema_preview_not_requested') }}</div>
              <div class="row q-gutter-xs">
                <q-chip v-for="c in t.not_requested" :key="'n-' + c.name" dense square outline color="grey-7" class="ai-chip">{{ c.name }}</q-chip>
              </div>
            </template>
            <q-banner
              v-for="c in t.default_switched_off"
              :key="'coff-' + c.name"
              dense
              rounded
              class="q-mt-sm bg-orange-1 text-orange-10"
            >{{ $t('ai_schema_preview_default_off', { name: c.name }) }}</q-banner>
          </div>
        </div>
      </div>
      <div class="text-caption text-grey-8 q-mt-sm" data-testid="ai-schema-preview-strict">
        {{
          preview.strict
            ? $t('ai_schema_preview_strict', { count: preview.property_count, limit: preview.property_limit })
            : $t('ai_schema_preview_not_strict', { count: preview.property_count, limit: preview.property_limit })
        }}
      </div>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { docFieldsApiService } from 'src/services';

export const PREVIEW_DOC_TYPES = ['INVOICE', 'ORDER_CONFIRMATION', 'DELIVERY_NOTE', 'CUSTOMER_ORDERS', 'QUOTE'];

export default defineComponent({
  name: 'AiSchemaPreview',
  data() {
    return {
      docType: 'INVOICE',
      loading: false,
      error: '' as string,
      preview: null as any,
    };
  },
  computed: {
    docTypeOptions(): { label: string; value: string }[] {
      return PREVIEW_DOC_TYPES.map((d) => ({ label: this.$t(d.toLowerCase()) || d, value: d }));
    },
  },
  mounted() {
    this.load();
  },
  methods: {
    async load() {
      this.loading = true;
      this.error = '';
      try {
        const res = await docFieldsApiService.getAiSchemaPreview(this.docType);
        if (res?.success) {
          this.preview = res.data;
        } else {
          this.preview = null;
          this.error = res?.message || this.$t('ai_schema_preview_failed');
        }
      } catch {
        this.preview = null;
        this.error = this.$t('ai_schema_preview_failed');
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>

<style scoped>
.ai-chip {
  font-family: ui-monospace, 'IBM Plex Mono', Menlo, monospace;
}
</style>
