<template>
  <div class="container-wrapper">
    <div class="container">
      <q-tabs
        v-model="tab"
        dense
        class="doc2-panels"
        align="justify"
        narrow-indicator
        active-class="highlighted-back"
        active-color="primary"
      >
        <q-tab name="general" :label="$t('general')" />
        <q-tab
          name="classification_rules"
          :label="$t('classification_rules_setting_label')"
        />
        <q-tab
          v-if="MODELS_LABELS_MODULE"
          name="custom_models"
          :label="$t('ai_models')"
        />
      </q-tabs>
    </div>

    <div class="q-pa-lg text-color-grey settings">
      <q-tab-panels class="page-background" v-model="tab" animated>
        <q-tab-panel name="classification_rules" class="no-padding">
          <ClassificationRulesList />
        </q-tab-panel>

        <q-tab-panel
          name="custom_models"
          class="no-padding"
          v-if="MODELS_LABELS_MODULE"
        >
          <ModelsList />
        </q-tab-panel>

        <q-tab-panel name="general" class="no-padding">
          <div class="settings-page-content">
            <!-- Document Splitting Section -->
            <DocbitsAccordionPanel
              v-model="expandedSections.documentSplitting"
              icon="mdi:content-cut"
              :title="$t('document_split')"
              :subtitle="$t('document_splitting_configuration')"
              bodyClass=""
            >
              <DocumentSplitting />
            </DocbitsAccordionPanel>

            <!-- Document Processing Section -->
            <DocbitsAccordionPanel
              v-model="expandedSections.documentProcessing"
              icon="mdi:file-document-multiple-outline"
              :title="$t('document_processing')"
              :subtitle="$t('document_processing_configuration')"
              bodyClass=""
            >
              <DocumentProcessing />
            </DocbitsAccordionPanel>

            <!-- Amount Formatting Section -->
            <DocbitsAccordionPanel
              v-model="expandedSections.amountFormatting"
              icon="mdi:currency-usd"
              :title="$t('amount_format')"
              :subtitle="$t('amount_formatting_configuration')"
              bodyClass=""
            >
              <AmountFormatting />
            </DocbitsAccordionPanel>

            <!-- Table Extraction Section -->
            <DocbitsAccordionPanel
              v-model="expandedSections.tableExtraction"
              icon="mdi:table"
              :title="$t('extraction')"
              :subtitle="$t('table_extraction_configuration')"
              bodyClass=""
            >
              <TableExtraction />
              <SupplierAIModelList />
            </DocbitsAccordionPanel>

            <!-- Electronic Document Section -->
            <DocbitsAccordionPanel
              v-model="expandedSections.electronicDocument"
              icon="mdi:file-document-outline"
              :title="$t('electronic_document')"
              :subtitle="$t('electronic_document_configuration')"
              bodyClass=""
            >
              <ElectrocDocument />
            </DocbitsAccordionPanel>
          </div>
        </q-tab-panel>
      </q-tab-panels>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { models_labels_module_setting } from 'src/constants';
import DocbitsAccordionPanel from 'src/single-component/DocbitsAccordionPanel.vue';
import ModelsList from 'src/pages/Settings/Components/ModelsAndLabels/ModelsList.vue';
import DocumentSplitting from 'src/pages/Settings/Components/ClassifyExtract/DocumentSplitting.vue';
import DocumentProcessing from 'src/pages/Settings/Components/ClassifyExtract/DocumentProcessing.vue';
import AmountFormatting from 'src/pages/Settings/Components/ClassifyExtract/AmountFormatting.vue';
import TableExtraction from 'src/pages/Settings/Components/ClassifyExtract/TableExtraction.vue';
import ClassificationRulesList from 'src/pages/Settings/Components/ClassificationRules/List.vue';
import ElectrocDocument from 'src/pages/Settings/Components/ClassifyExtract/ElectronicDocument.vue';
import SupplierAIModelList from 'src/pages/Settings/Components/ClassifyExtract/SupplierAIModelList.vue';

export default defineComponent({
  el: '#app',
  components: {
    DocumentSplitting,
    DocumentProcessing,
    AmountFormatting,
    TableExtraction,
    ClassificationRulesList,
    ModelsList,
    ElectrocDocument,
    SupplierAIModelList,
    DocbitsAccordionPanel,
  },
  data() {
    return {
      expandedSections: {
        documentSplitting: true,
        documentProcessing: true,
        amountFormatting: false,
        tableExtraction: false,
        electronicDocument: false,
      } as Record<string, boolean>,
    };
  },
  mounted: async function () {
    await this.startSettingsFetch();
    this.setTab();
  },
  methods: {
    async setTab() {
      this.tab = 'general';

      this.MODELS_LABELS_MODULE = await this.getSetting(models_labels_module_setting);
      if (
        this.$route.query &&
        this.$route.query.doc_type &&
        this.MODELS_LABELS_MODULE
      ) {
        this.tab = 'custom_models';
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { getSetting, startSettingsFetch } = settings_store;

    return {
      getSetting,
      startSettingsFetch,
      tab: ref('general'),
      MODELS_LABELS_MODULE: ref(false),
    };
  },
});
</script>
<style lang="scss"></style>
