<!--vbase-->
<template>
  <div class="flex flex-col gap-3">
    <!-- Toolbar -->
    <div class="flex items-center gap-2">
      <q-input
        class="width-500"
        outlined
        dense
        debounce="300"
        color="primary"
        v-model="filter"
        :label="$t('search_by_column')"
      >
        <template v-slot:append>
          <q-icon name="search" />
        </template>
      </q-input>
      <q-space />
      <f-btn
        :label="$t('add_new')"
        style="height: 40px"
        @click="addNew"
      />
    </div>

    <!-- Table -->
    <DocBitsTable
      :rows="filteredRows"
      :columns="columns"
      row-key="id"
      table-id="classification_extraction_table"
      :loading="loading"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: false,
        columnReorder: true,
        stickyLastColumn: true,
      }"
      :row-actions="rowActions"
      :column-order="columnOrder"
      no-data-label="no_record_found"
      flat-style
      table-height="500px"
      @row-action="handleRowAction"
      @column-reorder="handleColumnReorder"
    >
      <template #body-cell-rule_type="{ row }">
        {{ getLabelTranslationIfExists(row.rule_type, 'rule_type') }}
      </template>
      <template #body-cell-doc_type_key="{ row }">
        {{ getLabelTranslationIfExists(row.doc_type_key, 'doc_type_key') }}
      </template>
      <template #body-cell-sub_doc_type_key="{ row }">
        {{ getLabelTranslationIfExists(row.sub_doc_type_key, 'sub_doc_type_key') }}
      </template>
      <template #body-cell-sub_org_id="{ row }">
        {{ getLabelTranslationIfExists(row.sub_org_id, 'sub_org_id') }}
      </template>
    </DocBitsTable>
  </div>

  <q-dialog
    v-model="display_create_edit_dialog"
    persistent
    @keydown.esc="display_create_edit_dialog = false"
  >
    <createEdit :list_data="data" :model="edit_model"></createEdit>
  </q-dialog>

  <q-inner-loading :showing="loading" class="z-index-2">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin.js';
import type { dynamicObj } from 'src/pages/assets';
import { storeToRefs } from 'pinia';
import createEdit from 'src/pages/Settings/Components/ClassificationRules/EditCreate.vue';
import { classificationRulesApiService } from 'src/services';
import { useDropdownStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
import { LocalStorage } from 'quasar';
import { CONSTANTS } from 'src/constants';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {},
  components: {
    createEdit,
    DocBitsTable,
  },
  data() {
    return {};
  },
  computed: {
    filteredRows(): any[] {
      if (!this.filter) return this.rows.filter((r: any) => r.is_deleted === false);
      const lowerSearch = this.filter.toLowerCase();
      return this.rows.filter((row: any) => {
        if (row.is_deleted !== false) return false;
        for (const [key, value] of Object.entries(row)) {
          const val = value != null ? String(value).toLowerCase() : '';
          if (val.includes(lowerSearch)) return true;
          // Search display labels for dropdown columns
          const displayVal = this.getLabelTranslationIfExists(value, key);
          if (displayVal && displayVal.toLowerCase().includes(lowerSearch)) return true;
        }
        return false;
      });
    },
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const { getSubOrgsList, getRulesTypeList } = dropdown_store;
    const {
      doc_type_list,
      sub_types_list,
      subOrgList,
      classification_type_list,
    } = storeToRefs(dropdown_store);

    const rowActions: RowActionItem[] = [
      { key: 'edit', label: 'edit', icon: 'edit' },
      { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true },
    ];

    return {
      classification_type_list,
      getRulesTypeList,
      doc_type_list,
      sub_types_list,
      subOrgList,
      getSubOrgsList,
      display_create_edit_dialog: ref(false),
      display_list: ref(false),
      loading: ref(true),
      columns: ref([] as UnifiedTableColumn[]),
      columnOrder: ref([] as string[]),
      data: ref([] as any),
      rows: ref([] as any[]),
      filter: ref(''),
      edit_model: ref({}),
      rowActions,
    };
  },
  mounted: function () {
    this.initView();
    document.addEventListener('record_saved', this.recordSaved);
  },
  unmounted: function () {
    document.removeEventListener('record_saved', this.recordSaved);
  },
  methods: {
    async initView() {
      await this.getSubOrgsList();
      this.getRulesTypeList();
      this.prepareColumns();
      await this.getRecords();
    },
    async getRecords() {
      this.loading = true;
      const response = await classificationRulesApiService.getAll();
      this.loading = false;
      if (!Array.isArray(response) || response.length == 0) {
        return;
      }
      this.data = response;
      this.prepareRows();
    },

    recordSaved() {
      this.getRecords();
      this.display_create_edit_dialog = false;
    },

    getLabelTranslationIfExists(val: any, col_name: string) {
      if (!val) {
        val = '';
      }

      if (col_name == 'sub_org_id') {
        let filterRecord = this.subOrgList.filter((v: any) => {
          return v.value == val;
        });
        filterRecord = filterRecord[0] || null;
        val = !filterRecord ? '' : filterRecord.label;
      }

      if (col_name == 'doc_type_key') {
        let filterRecord = this.doc_type_list.filter((v: any) => {
          return v.value == val;
        });
        filterRecord = filterRecord[0] || null;
        val = !filterRecord ? '' : filterRecord.label;
      }

      if (col_name == 'sub_doc_type_key') {
        let filterRecord = this.sub_types_list.filter((v: any) => {
          return v.value == val;
        });
        filterRecord = filterRecord[0] || null;
        val = !filterRecord ? '' : filterRecord.label;
      }

      if (col_name == 'rule_type') {
        let filterRecord = this.classification_type_list.filter((v: any) => {
          return v.value == val;
        });
        filterRecord = filterRecord[0] || null;
        val = !filterRecord ? '' : filterRecord.label;
      }

      return String(val);
    },

    prepareColumns() {
      this.columns = [
        { name: 'rule_type', label: this.$t('type'), field: 'rule_type', align: 'left' },
        { name: 'rule_value_1', label: this.$t('pattern'), field: 'rule_value_1', align: 'left' },
        { name: 'doc_type_key', label: this.$t('document_type'), field: 'doc_type_key', align: 'left' },
        { name: 'sub_doc_type_key', label: this.$t('sub_type'), field: 'sub_doc_type_key', align: 'left' },
        { name: 'sub_org_id', label: this.$t('sub_org'), field: 'sub_org_id', align: 'left' },
      ] as UnifiedTableColumn[];

      // Restore saved column order
      const saved_columns = LocalStorage.getItem(
        CONSTANTS.classification_columns,
      ) as string;
      if (saved_columns) {
        try {
          const parsed = JSON.parse(saved_columns);
          this.columnOrder = parsed.map((c: any) => c.name).filter((n: string) => n !== 'action');
        } catch {
          // ignore invalid saved state
        }
      }
    },

    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      // Save column order in the legacy format for backward compatibility
      const orderedColumns = newOrder
        .map((name: string) => this.columns.find((c: any) => c.name === name))
        .filter(Boolean);
      LocalStorage.set(
        CONSTANTS.classification_columns,
        JSON.stringify(orderedColumns),
      );
    },

    prepareRows() {
      this.rows = this.data;
    },

    addNew() {
      this.edit_model = {};
      this.display_create_edit_dialog = true;
    },

    editRow(row: any) {
      this.edit_model = row;
      this.display_create_edit_dialog = true;
    },

    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'edit') {
        this.editRow(row);
      } else if (action === 'delete') {
        const index = this.rows.findIndex((r: any) => r.id === row.id);
        if (index !== -1) {
          this.deleteRow(index, row.id);
        }
      }
    },

    async deleteRow(index: number, id: string) {
      try {
        this.loading = true;
        const response = await classificationRulesApiService.delete(id);

        if (!response || response.success !== true) {
          throw response;
        }

        this.rows.splice(index, 1);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>
